import{_ as t,o as a,c as o,a8 as r}from"./chunks/framework.DpsX1MbM.js";const p=JSON.parse('{"title":"About SpecForge","description":"","frontmatter":{},"headers":[],"relativePath":"get_started/about.md","filePath":"sections/get_started/about.md","lastUpdated":1788846900000}'),i={name:"get_started/about.md"};function n(s,e,c,d,l,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="about-specforge" tabindex="-1">About SpecForge <a class="header-anchor" href="#about-specforge" aria-label="Permalink to &quot;About SpecForge&quot;">​</a></h1><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Speculative decoding is an important and powerful technique for speeding up inference without losing performance. Industries have used it extensively in production to better serve their users with lower latency and higher throughput. We have seen some open-source projects for training speculative decoding models, but most of them are not well-maintained or not directly compatible with SGLang. We prepared this project because we wish that the open-source community can enjoy a speculative decoding framework that is</p><ul><li>regularly maintained by the SGLang team: the code is runnable out-of-the-box</li><li>directly compatible with SGLang: no additional porting effort is required</li><li>able to provide online disaggregated training and both colocated and disaggregated offline training through one runtime, including consumer DP, offline USP, evaluation, checkpoint selection, and CUDA/ROCm/Ascend portability</li></ul><h2 id="sglang-ready" tabindex="-1">SGLang-ready <a class="header-anchor" href="#sglang-ready" aria-label="Permalink to &quot;SGLang-ready&quot;">​</a></h2><p>As SpecForge is built by the SGLang team, draft models trained with SpecForge can be exported for <a href="https://github.com/sgl-project/sglang" target="_blank" rel="noreferrer">SGLang</a> serving. Runtime checkpoints retain training state, so materialize a serving directory with the shared <code>specforge export</code> command. SGLang and Hugging Face export targets use the same checkpoint surface; there are no method-specific conversion scripts.</p>',6)])])}const u=t(i,[["render",n]]);export{p as __pageData,u as default};
